sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmName ?director ?directorName ?deathDate WHERE {
  VALUES ?film { dbr:Ridin'_Pretty dbr:How_Strange_to_Be_Named_Federico }

  # film name (prefer dbp:name)
  OPTIONAL { ?film dbp:name ?filmName . }
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER (lang(?filmLabel) = "en")
    BIND(?filmLabel AS ?filmName)
  }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  # director name (prefer dbp:name)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL {
    ?director rdfs:label ?dirLabel .
    FILTER (lang(?dirLabel) = "en")
    BIND(?dirLabel AS ?directorName)
  }

  # director death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDate . }
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
}
LIMIT 100

